#!/usr/bin/env python3
"""Apply final batch of prerequisites to DB."""
import base64, subprocess

def psql_update(slug: str, content: str):
    b64 = base64.b64encode(content.encode("utf-8")).decode("ascii")
    sql = (
        'UPDATE "Challenge" SET "starterSchema" = '
        f'convert_from(decode(\'{b64}\',\'base64\'),\'UTF8\') '
        f'WHERE slug = \'{slug}\' AND "starterSchema" IS NULL;'
    )
    result = subprocess.run(
        ["docker", "exec", "bitcode-postgres",
         "psql", "-U", "postgres", "-d", "bitcode", "-c", sql],
        capture_output=True, text=True
    )
    updated = "UPDATE 1" in result.stdout
    print(f"  {'OK  ' if updated else 'skip'} {slug}")

PREREQS_B64 = {
    "api-key-rotation-no-downtime": "",
    "build-monaco-editor-submission": "",
    "build-sse-logs": "",
    "cdn-cache-poisoning-prevention": "",
    "ci-gate-for-submissions": "",
    "claude-code-cicd-integration": "",
    "csp-nonce-implementation": "",
    "dependabot-security-automation": "",
    "dependency-audit-frontend": "",
    "design-rate-limiter": "",
    "env-variable-injection-security": "",
    "feature-flag-secure-deployment": "",
    "flyway-migration-management": "",
    "frontend-container-hardening": "",
    "frontend-secrets-leak-ci": "",
    "implement-permissions-model": "",
    "llm-audit-logging-compliance": "",
    "llm-observability-tracing": "",
    "mcp-server-project-integration": "",
    "multimodal-data-extraction": "",
    "plan-mode-architecture-decision": "",
    "prompt-injection-redteam-suite": "",
    "rate-limiter-distributed": "",
    "refactor-ai-generated-code": "",
    "sast-frontend-ci": "",
    "secure-file-upload": "",
    "security-headers-nginx": "",
    "session-fork-parallel-exploration": "",
    "sri-deployment-check": "",
    "subresource-integrity-cdn": "",
    "websocket-collab-presence": "",
}

PREREQS = {k: base64.b64decode(v).decode("utf-8") for k, v in PREREQS_B64.items()}

print(f"Applying {len(PREREQS)} final prerequisites...")
for slug, content in PREREQS.items():
    psql_update(slug, content)
print("\nDone.")
